type JsonLd = Record<string, any>;

function buildJsonLd(params: {
  siteUrl: string;
  pageUrl: string;
  lang: string;
  title: string;
  description: string;
  providerName: string;
  providerUrl: string;
  areaServed: string[];
  offers: { name: string; description: string }[];
  faqItems?: { q: string; a: string }[];
}): JsonLd[] {
  const { siteUrl, pageUrl, lang, title, description, providerName, providerUrl, areaServed, offers, faqItems = [] } = params;
  const service = {
    "@context": "https://schema.org", "@type": "Service", "@id": `${pageUrl}#service`,
    name: title, description,
    provider: { "@type": "Person", name: providerName, url: providerUrl },
    areaServed: areaServed.map((name) => ({ "@type": "AdministrativeArea", name })),
    availableChannel: { "@type": "ServiceChannel", serviceUrl: pageUrl },
    offers: offers.map((o, i) => ({ "@type": "Offer", "@id": `${pageUrl}#offer-${i + 1}`, name: o.name, description: o.description, url: pageUrl, priceCurrency: "CAD" })),
    inLanguage: lang,
  };
  const breadcrumb = {
    "@context": "https://schema.org", "@type": "BreadcrumbList", "@id": `${pageUrl}#breadcrumbs`,
    itemListElement: [
      { "@type": "ListItem", position: 1, name: "Home", item: siteUrl },
      { "@type": "ListItem", position: 2, name: "Services", item: `${siteUrl}/services/` },
      { "@type": "ListItem", position: 3, name: title, item: pageUrl },
    ],
  };
  const faqPage = faqItems.length ? {
    "@context": "https://schema.org", "@type": "FAQPage", "@id": `${pageUrl}#faq`,
    mainEntity: faqItems.map((item) => ({ "@type": "Question", name: item.q, acceptedAnswer: { "@type": "Answer", text: item.a } })),
  } : null;
  return [service, breadcrumb, faqPage].filter(Boolean) as JsonLd[];
}

function ArrowIcon() {
  return (
    <svg className="arrow" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true">
      <path d="M5 12h14M13 5l7 7-7 7" />
    </svg>
  );
}

